import { data, takaro } from '@takaro/helpers';

async function main() {
  const { gameServerId, module } = data;

  const moduleConfig = module.userConfig || {};
  const discordChannelId = moduleConfig.discordChannelId;

  if (!discordChannelId) {
    console.log('Discord channel ID not configured');
    return;
  }

  // 1. Pobieramy listę graczy online z komendy lp
  const lpResult = await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
    command: 'lp'
  });

  const output = lpResult.data.data.rawResult;
  const lines = output ? output.split('\n') : [];
  let onlineCount = 0;

  for (const line of lines) {
    const nameMatch = line.match(/id=\d+,\s*([^,]+),/);
    const steamIdMatch = line.match(/Steam_(\d+)/);
    if (nameMatch && steamIdMatch) {
      onlineCount++;
    }
  }

  // 2. Czas lokalny CEST (+2h) z zachowaniem pełnej godziny dla slotu
  const now = new Date();
  now.setHours(now.getHours() + 2);

  const timeString = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

  const currentSlotTime = new Date(now);
  currentSlotTime.setMinutes(0, 0, 0);
  const currentSlotTimestamp = currentSlotTime.getTime();

  // 3. Pobieramy historyczną historię 48h z bazy Takaro
  const variableSearch = await takaro.variable.variableControllerSearch({
    filters: {
      key: ['activity_chart_rolling_data_48h'],
      gameServerId: [gameServerId]
    }
  });

  let storedHistory = [];
  let chartDataVarId = null;

  if (variableSearch.data.data.length > 0) {
    const foundVar = variableSearch.data.data[0];
    chartDataVarId = foundVar.id;
    try {
      const parsed = JSON.parse(foundVar.value);
      if (Array.isArray(parsed)) {
        storedHistory = parsed;
      }
    } catch (e) {
      // błąd parsowania
    }
  }

  // Budujemy okno ostatnich 48 godzin
  let rollingData = [];
  for (let i = 47; i >= 0; i--) {
    const slotTime = new Date(currentSlotTimestamp);
    slotTime.setHours(slotTime.getHours() - i);
    const slotTimestamp = slotTime.getTime();

    const existing = storedHistory.find(h => h.timestamp === slotTimestamp);

    if (slotTimestamp === currentSlotTimestamp) {
      const peak = existing ? Math.max(existing.peak, onlineCount) : onlineCount;
      rollingData.push({ timestamp: slotTimestamp, peak: peak });
    } else {
      rollingData.push({
        timestamp: slotTimestamp,
        peak: existing ? existing.peak : 0
      });
    }
  }

  // Zapisujemy zaktualizowaną historię do bazy Takaro
  const storedDataJson = JSON.stringify(rollingData);
  if (chartDataVarId) {
    await takaro.variable.variableControllerUpdate(chartDataVarId, {
      value: storedDataJson
    });
  } else {
    await takaro.variable.variableControllerCreate({
      key: 'activity_chart_rolling_data_48h',
      value: storedDataJson,
      moduleId: data.module.moduleId,
      gameServerId: gameServerId
    });
  }

  // 4. Generowanie wierszy z ciągłym śledzeniem dnia
  const maxLimit = 8;
  let lastDayStr = '';

  const rows = rollingData.map((h, index) => {
    const slotDate = new Date(h.timestamp);
    const day = String(slotDate.getDate()).padStart(2, '0');
    const month = String(slotDate.getMonth() + 1).padStart(2, '0');
    const hours = String(slotDate.getHours()).padStart(2, '0');

    const dayStr = `${day}.${month}`;

    let dateLabel = '';
    if (dayStr !== lastDayStr) {
      dateLabel = `${dayStr} `;
      lastDayStr = dayStr;
    } else {
      dateLabel = '      ';
    }

    const hourLabel = `${dateLabel}${hours}:00`;
    const peak = h.peak || 0;

    const filledCount = Math.min(peak, maxLimit);
    const emptyCount = maxLimit - filledCount;
    const bar = '🟩'.repeat(filledCount) + '⬛'.repeat(emptyCount);

    const isCurrent = (index === rollingData.length - 1);
    const pointer = isCurrent ? ' 🡫' : '';

    const countStr = peak;

    return `${hourLabel} ${bar} (${countStr})${pointer}`;
  });

  // Całość w jednym bloku w description
  const fullChart = '```\n' + rows.join('\n') + '\n```';

  const embed = {
    color: 0x024b30,
    title: '♻️ ....... AKTYWNOŚĆ SERWERA (48H) ....... ♻️',
    description: fullChart,
    footer: {
      text: `Aktualizacja co 5m.                                        Ostatnia ${timeString}`
    }
  };

  // 5. Wysyłanie / edycja wiadomości na Discordzie
  const messageIdSearch = await takaro.variable.variableControllerSearch({
    filters: {
      key: ['activity_chart_rolling_msg_id_48h'],
      gameServerId: [gameServerId]
    }
  });

  let messageId = null;
  let variableRecordId = null;

  if (messageIdSearch.data.data.length > 0) {
    const foundMsgVar = messageIdSearch.data.data[0];
    messageId = foundMsgVar.value;
    variableRecordId = foundMsgVar.id;
  }

  if (messageId) {
    try {
      await takaro.discord.discordControllerUpdateMessage(discordChannelId, messageId, {
        embed: embed
      });
    } catch (error) {
      const newMessage = await takaro.discord.discordControllerSendMessage(discordChannelId, {
        embed: embed
      });
      if (variableRecordId) {
        await takaro.variable.variableControllerUpdate(variableRecordId, {
          value: newMessage.data.data.id
        });
      }
    }
  } else {
    const newMessage = await takaro.discord.discordControllerSendMessage(discordChannelId, {
      embed: embed
    });
    await takaro.variable.variableControllerCreate({
      key: 'activity_chart_rolling_msg_id_48h',
      value: newMessage.data.data.id,
      moduleId: data.module.moduleId,
      gameServerId: gameServerId
    });
  }
}

await main();
